const input = $input.first().json;
const errors = [];
if (!Array.isArray(input.imageUrls) || input.imageUrls.length === 0) errors.push('imageUrls is required and must be a non-empty array');
if (!input.title || typeof input.title !== 'string') errors.push('title is required');
if (input.title && input.title.length > 90) errors.push('title must be 90 characters or fewer (TikTok photo post title cap)');
if (!input.description || typeof input.description !== 'string') errors.push('description is required');
const validPrivacy = ['PUBLIC_TO_EVERYONE', 'MUTUAL_FOLLOW_FRIENDS', 'SELF_ONLY'];
if (!validPrivacy.includes(input.privacyLevel)) errors.push('privacyLevel must be one of ' + validPrivacy.join(', '));
if (errors.length) {
  throw new Error('tiktok auto post: invalid input - ' + errors.join('; '));
}
return [{ json: {
  imageUrls: input.imageUrls,
  title: input.title,
  description: input.description,
  privacyLevel: input.privacyLevel,
  publishNow: input.publishNow === true
} }];

const input = $input.first().json;
const TIKTOK_ACCOUNT_ID = '6a346bfa5f7d1751ab060a9a';

// Zernio only actually calls TikTok's API when publishNow:true is sent (publishNow:false just
// saves the post inertly inside Zernio and never contacts TikTok at all). To get a TikTok
// Creator Inbox draft, we must send publishNow:true to Zernio AND tiktokSettings.draft:true,
// which tells TikTok's own API to route the publish into Creator Inbox instead of going live.
// TikTok photo posts: top-level content = title (<=90 chars, hashtags/URLs stripped),
// tiktokSettings.description = full caption (up to 4000 chars). They are NOT interchangeable.
const payload = {
  content: input.title,
  mediaItems: input.imageUrls.map(url => ({ type: 'image', url })),
  platforms: [
    { platform: 'tiktok', accountId: TIKTOK_ACCOUNT_ID }
  ],
  tiktokSettings: {
    privacy_level: input.privacyLevel,
    allow_comment: true,
    media_type: 'photo',
    photo_cover_index: 0,
    description: input.description,
    auto_add_music: true,
    content_preview_confirmed: true,
    express_consent_given: true,
    draft: !input.publishNow
  },
  publishNow: true
};

return [{ json: payload }];

const resp = $input.first().json;
const wasDraft = $('Build Zernio payload').first().json.tiktokSettings.draft === true;
return [{ json: {
  postId: resp._id || resp.post?._id || null,
  status: resp.status || (wasDraft ? 'sent_to_creator_inbox' : 'published'),
  mode: wasDraft ? 'draft (needs manual confirm in TikTok Creator Inbox)' : 'published live',
  raw: resp
} }];
